package com.enterpriseos;

import java.util.*;
import java.util.regex.Pattern;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class MentionService {
    private final AutomationSupport s;private final CustomAccessPolicy custom;
    public MentionService(AutomationSupport s,CustomAccessPolicy custom){this.s=s;this.custom=custom;}
    public void fromTaskComment(Principal actor,String taskId,String commentId,String commentText){fromTaskComment(actor,taskId,commentId,commentText,null);}
    public void fromTaskComment(Principal actor,String taskId,String commentId,String commentText,Object explicitUserIds){var task=s.first(s.db.queryForList("SELECT payload FROM business_records WHERE tenant_id=? AND kind='tasks' AND id=?",actor.tenantId(),taskId),"Task");String project=Objects.toString(s.decode(task.get("payload")).get("projectId"),"");create(actor,commentText,explicitUserIds,project,"task-comment:"+commentId);}
    @Transactional public Map<String,Object> create(Principal actor,String body,Object explicitUserIds,String projectId,String eventKey){s.org(actor);if(body==null||body.isBlank()||body.length()>2000)throw new ApiException(400,"Mention text must contain 1–2000 characters.");LinkedHashSet<String> recipients=new LinkedHashSet<>();if(explicitUserIds!=null){if(!(explicitUserIds instanceof List<?> ids)||ids.size()>20||ids.stream().anyMatch(id->!(id instanceof String text)||text.length()!=36))throw new ApiException(400,"Choose at most 20 user IDs.");for(Object id:(List<?>)explicitUserIds)recipients.add(id.toString());}var ids=Pattern.compile("@\\{([0-9a-fA-F-]{36})}").matcher(body);while(ids.find())recipients.add(ids.group(1));var emails=Pattern.compile("(?<![A-Za-z0-9])@([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,})").matcher(body);while(emails.find()){var users=s.db.queryForList("SELECT u.id FROM users u JOIN memberships m ON m.user_id=u.id WHERE m.tenant_id=? AND LOWER(u.email)=? AND m.status='ACTIVE' AND u.status='ACTIVE'",String.class,actor.tenantId(),emails.group(1).toLowerCase(Locale.ROOT));if(users.isEmpty())throw new ApiException(400,"A mentioned email is not an active member of this organization.");recipients.add(users.getFirst());}if(recipients.size()>20)throw new ApiException(400,"Mention at most 20 members.");if(recipients.isEmpty())return Map.of("recipientCount",0);if(projectId!=null&&!projectId.isBlank())projectAccess(actor,projectId);String id=s.id();for(String user:recipients){var row=s.first(s.db.queryForList("SELECT u.name,u.email,m.role FROM users u JOIN memberships m ON m.user_id=u.id WHERE m.tenant_id=? AND u.id=? AND m.status='ACTIVE' AND u.status='ACTIVE'",actor.tenantId(),user),"Mention recipient");Principal recipient=new Principal(user,actor.tenantId(),row.get("name").toString(),row.get("email").toString(),row.get("role").toString());if(!custom.allowed(recipient,"GET","/api/v1/org/notifications"))throw new ApiException(403,"A recipient cannot access notification content under their current custom role.");if(projectId!=null&&!projectId.isBlank())projectAccess(recipient,projectId);s.events.notify(actor.tenantId(),user,eventKey+":"+user,"MENTION",actor.name()+" mentioned you",body);}s.db.update("INSERT INTO notification_mentions(id,tenant_id,author_id,project_id,body,recipient_ids,event_key) VALUES (?,?,?,?,?,?,?)",id,actor.tenantId(),actor.userId(),projectId==null||projectId.isBlank()?null:projectId,body,s.encode(recipients),eventKey);return Map.of("id",id,"recipientCount",recipients.size());}
    private void projectAccess(Principal p,String id){if(!custom.allowed(p,"GET","/api/v1/org/records/tasks"))throw new ApiException(403,"A mention recipient cannot read project tasks under their custom role.");var row=s.first(s.db.queryForList("SELECT payload FROM business_records WHERE tenant_id=? AND kind='projects' AND id=?",p.tenantId(),id),"Project");var project=s.decode(row.get("payload"));if(Set.of("ADMIN","MANAGER","AUDITOR").contains(p.role())||p.userId().equals(project.get("ownerId"))||(project.get("memberIds") instanceof List<?> members&&members.contains(p.userId())))return;throw new ApiException(403,"Mention content cannot be shared with a user outside this project.");}
}
